110: 
111: 	int z = rv->tz >> FLOATNS;//ddd
112: 	if(z > ccDistZMin)
113: 	{
114: 		int lev = ((z - ccDistZMin) << (13 - ShiftMAPCELL_MULT)) >> 8;
115: 		if(lev >= 256)
