122: 	}
123: 
124: 	for(int cnt = 0; cnt < 4; cnt++)
125: 	{
126: 		BlinkColor[cnt] += rv->bCol[cnt];
127: 		if(BlinkColor[cnt] > 255)
128: 		{
129: 			short spe = rv->bSpe[cnt] + (BlinkColor[cnt] - 256);
130: 			Color[cnt] = 255;
131: 			if(spe > 255)
